-- 0305-society-historical-events.sql — Historical Events (Sử biến theo lịch 184–220)

CREATE TABLE IF NOT EXISTS so_historical_event (
    code               TEXT    PRIMARY KEY,
    year               INTEGER NOT NULL,
    month              INTEGER NOT NULL CHECK (month BETWEEN 1 AND 12),
    day                INTEGER NOT NULL CHECK (day BETWEEN 1 AND 30),
    day_index          INTEGER NOT NULL,
    title_vi           TEXT    NOT NULL,
    narrative_vi       TEXT    NOT NULL,
    rumor_title_vi     TEXT    NOT NULL,
    rumor_narrative_vi TEXT    NOT NULL,
    primary_citadel_id INTEGER NOT NULL,
    related_citadels   TEXT    NOT NULL,
    related_npcs       TEXT    NOT NULL,
    background_key     TEXT    NOT NULL,
    choices_json       TEXT    NOT NULL,
    impacts_json       TEXT    NOT NULL,
    status             TEXT    NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'occurred', 'viewed')),
    occurred_date      TEXT,
    choice_code        TEXT
);

CREATE INDEX IF NOT EXISTS ix_so_historical_event_day ON so_historical_event(day_index, status);

INSERT OR IGNORE INTO so_historical_event (
    code, year, month, day, day_index, title_vi, narrative_vi,
    rumor_title_vi, rumor_narrative_vi, primary_citadel_id, related_citadels, related_npcs, background_key,
    choices_json, impacts_json, status
) VALUES
(
    'evt_184_khan_vang', 184, 8, 15, 66104,
    'Khăn Vàng đại khởi nghĩa — Quảng Tông khói lửa',
    'Thiên Công Tướng Quân Trương Giác phất cờ Thái Bình Đạo tại Quảng Tông, hô vang khẩu hiệu Trời xanh đã chết, trời vàng đương lập. Hàng chục vạn nông dân đội khăn vàng nổi dậy khắp Ký Châu và Dự Châu làm rung chuyển cơ đồ Đông Hán. Bắc Quân Trung Lang Tướng Lư Thực và Tả Trung Lang Tướng Hoàng Phủ Tung dẫn đại quân triều đình vây hãm thành Quảng Tông suốt nhiều tháng ròng. Giữa vòng vây trùng điệp, Trương Giác lâm trọng bệnh qua đời trong trại, nghĩa quân Khăn Vàng tan vỡ nhưng ngọn lửa loạn thế đã lan khắp Trung Nguyên.',
    'Điềm báo Khăn Vàng đại biến tại Quảng Tông',
    'đạo chúng Thái Bình Đạo đang tụ hội hàng vạn người quanh thành, lương thảo và thảo dược khan hiếm từng ngày',
