    '[{"Kind":"city_owner","CitadelId":1,"TargetCitadelId":null,"NpcCode":"npc_0023","FactionId":6,"ShockType":null,"DurationDays":0,"SeverityPermille":0,"NoteVi":"Đổng Trác khống chế kinh thành Lạc Dương"},{"Kind":"npc_move","CitadelId":1,"TargetCitadelId":null,"NpcCode":"npc_0023","FactionId":6,"ShockType":null,"DurationDays":0,"SeverityPermille":0,"NoteVi":"Đổng Trác tọa trấn Lạc Dương"},{"Kind":"npc_move","CitadelId":1,"TargetCitadelId":null,"NpcCode":"npc_0057","FactionId":6,"ShockType":null,"DurationDays":0,"SeverityPermille":0,"NoteVi":"Lữ Bố quy hàng Đổng Trác tại Lạc Dương"},{"Kind":"npc_allegiance","CitadelId":1,"TargetCitadelId":null,"NpcCode":"npc_0057","FactionId":6,"ShockType":null,"DurationDays":0,"SeverityPermille":0,"NoteVi":"Lữ Bố nhận Đổng Trác làm nghĩa phụ"},{"Kind":"npc_move","CitadelId":3,"TargetCitadelId":null,"NpcCode":"npc_0018","FactionId":4,"ShockType":null,"DurationDays":0,"SeverityPermille":0,"NoteVi":"Viên Thiệu rút khỏi Lạc Dương về Nghiệp Thành"},{"Kind":"price_shock","CitadelId":1,"TargetCitadelId":null,"NpcCode":null,"FactionId":null,"ShockType":"SIEGE","DurationDays":25,"SeverityPermille":2000,"NoteVi":"Quân Tây Lương trưng thu lương thực tại Lạc Dương"}]',
    'pending'
