    '[{"Key":"mourn_tiger","LabelVi":"Chi 70 Quan lập đàn tế Giang Đông Mãnh Hổ (+Uy danh, +Đức độ)","SubtitleVi":"Bày tỏ lòng kính trọng bậc anh hùng mở cõi Giang Đông","CostCopper":70,"RewardCopper":0,"FameDelta":16,"VirtueDelta":6},{"Key":"trade_timber","LabelVi":"Cung ứng gỗ đóng thuyền cho thủy trại Hán Thủy (+130 Quan)","SubtitleVi":"Thủy chiến Kinh Tương khiến nhu cầu gỗ thuyền tăng cao","CostCopper":30,"RewardCopper":130,"FameDelta":4,"VirtueDelta":0},{"Key":"continue","LabelVi":"Tiếp tục","SubtitleVi":"Lắng nghe tiếng chuông báo tang bên sông Hán","CostCopper":0,"RewardCopper":0,"FameDelta":0,"VirtueDelta":0}]',
    '[{"Kind":"npc_death","CitadelId":10,"TargetCitadelId":null,"NpcCode":"npc_0014","FactionId":null,"ShockType":null,"DurationDays":0,"SeverityPermille":0,"NoteVi":"Trúng tên phục kích tử trận tại Hiện Sơn ngoại thành Tương Dương năm Tân Mùi 191"},{"Kind":"npc_move","CitadelId":13,"TargetCitadelId":null,"NpcCode":"npc_0048","FactionId":3,"ShockType":null,"DurationDays":0,"SeverityPermille":0,"NoteVi":"Tôn Sách kế thừa di chí phụ thân tại Giang Đông"},{"Kind":"route_danger","CitadelId":10,"TargetCitadelId":12,"NpcCode":null,"FactionId":null,"ShockType":"route_danger","DurationDays":25,"SeverityPermille":1700,"NoteVi":"Thủy quân Kinh Châu và Giang Đông giao tranh dọc Hán Thủy"},{"Kind":"price_shock","CitadelId":10,"TargetCitadelId":null,"NpcCode":null,"FactionId":null,"ShockType":"SIEGE","DurationDays":20,"SeverityPermille":1900,"NoteVi":"Tương Dương đóng chặt cổng thành phòng thủ quân Giang Đông"}]',
    'pending'
