    '[{"Key":"gift_scrolls","LabelVi":"Chi 70 Quan dâng tặng trúc giản cổ thư cho thảo lư (+Uy danh, +Đức độ)","SubtitleVi":"Kết giao cùng các danh sĩ Kinh Tương dưới trướng Ngọa Long","CostCopper":70,"RewardCopper":0,"FameDelta":24,"VirtueDelta":8},{"Key":"trade_tea","LabelVi":"Mở tiệc trà đạo chiêu đãi văn sĩ Tương Dương (+110 Quan)","SubtitleVi":"Danh sĩ bốn phương đổ về Tương Dương luận bàn thời cuộc","CostCopper":20,"RewardCopper":110,"FameDelta":8,"VirtueDelta":2},{"Key":"continue","LabelVi":"Tiếp tục","SubtitleVi":"Lắng nghe Long Trung Đối Sách vang vọng trong tuyết trắng","CostCopper":0,"RewardCopper":0,"FameDelta":0,"VirtueDelta":0}]',
