(
    'evt_214_luu_bi_ich_chau', 214, 6, 12, 76841,
    'Bình định Tây Xuyên — Lưu Bị tiến vào Thành Đô lập cơ nghiệp Ba Thục',
    'Theo lời mời của Ích Châu Mục Lưu Chương vào Tây Xuyên chống Trương Lỗ ở Hán Trung, Lưu Bị cùng quân sư Bàng Thống và Pháp Chính từng bước thu phục lòng người đất Thục. Sau khi Bàng Thống tử trận tại gò Lạc Phượng, Gia Cát Lượng cùng Trương Phi và Triệu Vân lập tức từ Kinh Châu dẫn quân ngược dòng Trường Giang tiến vào hội sư với Lưu Bị trước thành Thành Đô. Khi Mã Siêu từ Tây Lương bất ngờ quy thuận Lưu Bị và dẫn thiết kỵ áp sát cửa Bắc, tinh thần quân dân trong thành hoàn toàn rúng động. Không nỡ để bá tánh Thành Đô chịu cảnh máu chảy đầu rơi, Lưu Chương mở cổng thành dâng ấn tín đầu hàng, giúp Lưu Bị chính thức làm chủ vùng đất Thiên Phủ trù phú.',
    'Đại quân Lưu Bị và Gia Cát Lượng đang hội sư trước Thành Đô',
    'cánh quân của Khổng Minh, Trương Phi đã vượt qua các ải hiểm Ba Thục để cùng Lưu Bị bao vây Thành Đô của Lưu Chương',
    15, '15,14,12', 'npc_0001,npc_0025,npc_0021', 'gate',
    '[{"Key":"stabilize_shu","LabelVi":"Chi 100 Quan bình ổn giá muối sắt và phát chẩn Thành Đô (+Uy danh, +Đức độ)","SubtitleVi":"Hưởng ứng chính sách an dân khoan hòa của Gia Cát Lượng tại Tây Xuyên","CostCopper":100,"RewardCopper":0,"FameDelta":24,"VirtueDelta":10},{"Key":"export_brocade","LabelVi":"Chi 70 Quan thu mua Thục Cẩm vừa mở thông đường (+190 Quan)","SubtitleVi":"Thương lộ Ba Thục khai thông giúp gấm vóc Thành Đô sinh lời lớn","CostCopper":70,"RewardCopper":190,"FameDelta":10,"VirtueDelta":2},{"Key":"continue","LabelVi":"Tiếp tục","SubtitleVi":"Chứng kiến cờ hiệu Hán Trung Vương tung bay trên thành Thành Đô","CostCopper":0,"RewardCopper":0,"FameDelta":0,"VirtueDelta":0}]',
