(
    'evt_219_quan_vu_kinh_chau', 219, 12, 15, 78824,
    'Bạch y độ giang — Quan Vũ thất thủ Kinh Châu, tuẫn tiết Mạch Thành',
    'Mùa thu năm Kỷ Hợi, Quan Vũ phát binh từ Giang Lăng bắc phạt Tương Phàn, dâng nước sông Hán Thủy nhấn chìm bảy đạo quân Ngụy và bắt sống Vu Cấm khiến Tào Tháo kinh hãi tính chuyện dời đô. Tuy nhiên phía sau lưng, Đô Đốc Đông Ngô Lữ Mông giả bệnh nhường quyền cho Lục Tốn để làm Quan Vũ mất cảnh giác, rồi cho tinh binh mặc áo trắng giả làm thương nhân vượt sông đánh úp chiếm trọn Giang Lăng trong đêm. Bị quân Ngụy của Từ Hoảng đánh mặt trước và quân Ngô cắt đứt đường về phía sau, đại quân Quan Vũ tan rã phải rút vào cô thành Mạch Thành. Đêm mười lăm tháng chạp, Quan Vân Trường cùng con trưởng Quan Bình phá vây tại Lâm Thư sa vào ổ phục kích của quân Ngô và hiên ngang chịu chết chứ không khuất phục.',
    'Thương thuyền áo trắng khả nghi xuất hiện dọc bến sông Giang Lăng',
    'trong lúc Quan Vũ đang dốc toàn lực vây đánh Tương Phàn, nhiều đoàn thuyền buôn mặc áo trắng từ Giang Đông đang âm thầm áp sát các đài canh ven sông',
    12, '12,10,13', 'npc_0003,npc_0050,npc_0019', 'field',
    '[{"Key":"build_shrine","LabelVi":"Chi 120 Quan lập miếu thờ Võ Thánh Quan Vân Trường (+Uy danh, +Đức độ)","SubtitleVi":"Bách tính Kinh Sở và nghĩa sĩ thiên hạ đời đời kính ngưỡng trung nghĩa của Quan Công","CostCopper":120,"RewardCopper":0,"FameDelta":30,"VirtueDelta":15},{"Key":"evacuate_goods","LabelVi":"Chi 50 Quan thuê thuyền chuyển hàng khỏi Giang Lăng (+160 Quan)","SubtitleVi":"Kịp thời sơ tán hàng hóa thương hội trước khi chiến sự Ngô – Thục nổ ra","CostCopper":50,"RewardCopper":160,"FameDelta":6,"VirtueDelta":0},{"Key":"continue","LabelVi":"Tiếp tục","SubtitleVi":"Kính cẩn nghiêng mình trước anh linh Võ Thánh","CostCopper":0,"RewardCopper":0,"FameDelta":0,"VirtueDelta":0}]',
