(
    'evt_220_tao_phi_xung_de', 220, 10, 25, 79134,
    'Thiện nhượng đài Thụ Thiền — Tào Phi xưng đế lập triều Đại Ngụy',
    'Đầu năm Canh Tý, Ngụy Vương Tào Tháo qua đời tại Lạc Dương, thế tử Tào Phi kế vị ngôi Vương và nhanh chóng củng cố quyền lực với sự phò tá của Tư Mã Ý và Trần Quần. Tháng mười năm ấy, sau ba lần dâng biểu ép Hán Hiến Đế Lưu Hiệp ban chiếu nhường ngôi, Tào Phi dựng đài Thụ Thiền cao lớn tại Phồn Dương ngoại thành Hứa Xương. Trước hàng vạn giáp sĩ và trăm quan văn võ, Hán Hiến Đế trao lại Ngọc Tỷ, chấm dứt hơn bốn trăm năm quốc thống của vương triều nhà Hán. Tào Phi chính thức đăng cơ Hoàng Đế, đặt quốc hiệu Đại Ngụy, đổi niên hiệu Hoàng Sơ và định đô tại Lạc Dương, mở màn thời đại Tam Quốc Ngụy – Thục – Ngô phân tranh thiên hạ.',
    'Đài Thụ Thiền đang được gấp rút xây dựng giữa Hứa Xương và Lạc Dương',
    'Ngụy Vương Tào Phi đã triệu tập bá quan văn võ về Hứa Xương, chuẩn bị đại lễ nhận chiếu nhường ngôi từ Hán Hiến Đế',
    1, '1,7,15,13', 'npc_0073,npc_0039,npc_0001', 'hall',
    '[{"Key":"uphold_han_memory","LabelVi":"Chi 100 Quan khắc bia tưởng niệm bốn trăm năm nhà Hán (+Uy danh, +Đức độ)","SubtitleVi":"Giữ trọn khí tiết sĩ phu giữa buổi giao thời triều đại","CostCopper":100,"RewardCopper":0,"FameDelta":28,"VirtueDelta":12},{"Key":"new_dynasty_charter","LabelVi":"Chi 80 Quan xin giấy phép thông thương tân triều (+210 Quan)","SubtitleVi":"Mở rộng thương hội tại Lạc Dương và Hứa Xương dưới niên hiệu Hoàng Sơ","CostCopper":80,"RewardCopper":210,"FameDelta":10,"VirtueDelta":-2},{"Key":"continue","LabelVi":"Tiếp tục","SubtitleVi":"Khép lại kỷ nguyên Đông Hán, bước vào thời đại Tam Quốc","CostCopper":0,"RewardCopper":0,"FameDelta":0,"VirtueDelta":0}]',
